function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'ma_dvcs');
	var a = ['tk'];
	if (!f._extensions) f.request('GetDefaultValue', 'SetDefaultValue', a);
		else setReferenceValue(f, a);
	&ReportSign.Filter.Active;
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, dFrom = f.getItem('tu_ngay').value, dTo = f.getItem('den_ngay').value, x = f.getItemValue('mau_bc'), q = (f.getItemValue('chon_tt') == '1');
			var b = (f.getItemValue('isbalance') == 1), r = f.getItemValue('kieu_bc');
			g._alterTitle = [null, [['%s', f.getItemValue('tk'), true], ['%d1', dFrom, true], ['%d2', dTo, true]]];
			g._hiddenFields = [
				{Fields: 'ps_no_nt, ps_co_nt, no_dk_nt, co_dk_nt, no_ck_nt, co_ck_nt', Value: (x == '10' || x == '30')}
				//,{Fields: 'nc_dk2, nc_ck2', Value: (x == '20' || x == '40')}
			];
			g._hiddenForms = [
				{Form: [0, 1, 9, 10, 28, 29, 30, 31, 32, 33], Value: (r == '1' || b || !q)},
				{Form: [2, 3, 11, 12, 37, 38, 39, 40, 41, 42], Value: (r == '1' || !b || !q)},
				{Form: [4, 5, 13, 14], Value: (r == '2' || b || !q)},
				{Form: [6, 7, 15, 16], Value: (r == '2' || !b || !q)},
				{Form: [8], Value: (!q)},
				{Form: [17, 18, 25, 26, 27], Value: (r == '1' || b || q)},
				{Form: [19, 20, 34, 35, 36], Value: (r == '1' || !b || q)},
				{Form: [21, 22], Value: (r == '2' || b || q)},
				{Form: [23, 24], Value: (r == '2' || !b || q)}
			];
			g._queryFilterString = getQueryFilterString(f, 'tu_ngay, den_ngay, tk, ma_dvcs, mau_bc');
			if (g._$k != null) g._$k = [];
			remove$GridReport$Filter(g);
			break;
		case 'SetDefaultValue':
			f.setItemControlBehavior('ten_tk%l', result[0].Value, null, true);
			if (result[1].Value) f.setItemValue('tk', '');
			break;
		default:
			break;
	}
}
function setReferenceValue(f, a) {
	for (var i = 0; i < a.length; i++) {
		var r = $func.findField(a[i], f._fields).ItemReference;
		f.setItemValue(r, $func.findMemvar(r, f._extensions).NewValue);
	}
}
